    text: 'Paciente de 32 anos, sexo feminino, branca, admitida com história de hipertensão arterial há 15 anos. Há cinco anos, foi submetida à nefrectomia esquerda, devido a acidente automobilístico com trauma renal severo. Faz uso de Losartana e Furosemida, e evoluiu com aumento nos níveis de creatinina, que atingiram 2,8 mg/dL. A investigação por meio de arteriografia renal seletiva à direita mostrou os achados na imagem aqui demonstrados. Diante do quadro clínico, assinale a alternativa correta:\n\nI — O diagnóstico principal é de estenose da artéria renal secundária à doença aterosclerótica pela hipertensão arterial sistêmica.\nII — Essa doença acomete principalmente pacientes do sexo masculino com mais de 50 anos de idade que desenvolvem ou pioram da hipertensão.\nIII — A ultrassonografia com Doppler da artéria renal é padrão-ouro para o diagnóstico dessa condição por ser um método não invasivo e isento de radiação ionizante.',
